update public.learning_paths
set
  title = 'Music History II (Classical-Romantic)',
  goal = 'Music History II (Classical-Romantic)',
  summary = 'Music History II surveys Western art music from the galant and Classical style through late Romanticism. Students study Haydn, Mozart, Beethoven, Schubert, Schumann, Verdi, Wagner, Brahms, Tchaikovsky, Mahler, Strauss, and other central figures while also asking how institutions, technology, markets, gender, nation, empire, criticism, and performance practice shaped the repertory. The course balances listening, score study, primary sources, historical writing, and performance-aware analysis. Students learn not only to identify styles and works, but to explain why a musical event mattered in its own social world and how later canons made it matter differently.',
  data = $mh2json${"slug": "music-history-ii-classical-romantic", "title": "Music History II (Classical-Romantic)", "description": "Music History II surveys Western art music from the galant and Classical style through late Romanticism. Students study Haydn, Mozart, Beethoven, Schubert, Schumann, Verdi, Wagner, Brahms, Tchaikovsky, Mahler, Strauss, and other central figures while also asking how institutions, technology, markets, gender, nation, empire, criticism, and performance practice shaped the repertory. The course balances listening, score study, primary sources, historical writing, and performance-aware analysis. Students learn not only to identify styles and works, but to explain why a musical event mattered in its own social world and how later canons made it matter differently.", "topics": [{"id": "581327b6-7a35-4738-a5fa-3e03d26a9d5b", "type": "topic", "title": "The Galant and Classical Style", "description": "This unit frames the mid-eighteenth century as a change in musical language, audience, patronage, phrase structure, and public taste rather than a simple stylistic reset.", "children": [{"id": "dd35ec46-6c91-4be3-8694-9c2ff125a6cb", "type": "subtopic", "title": "Galant Style and Empfindsamkeit", "children": [{"id": "15299ca8-02ce-4f12-8a0c-455f95f34e4e", "type": "concept", "title": "Periodic phrasing and balanced antecedent-consequent design"}, {"id": "0f422b87-8a3f-4e50-a24f-3181d48e3d45", "type": "concept", "title": "Alberti bass, light texture, and melody-dominated homophony"}, {"id": "9827f3ad-c800-4759-b972-3968bfdaef19", "type": "concept", "title": "C. P. E. Bach, empfindsamkeit, and expressive instability"}], "description": "Students learn to hear clarity, elegance, surprise, and expressive sensitivity as historically situated ideals."}, {"id": "2e536715-1217-4255-96f0-e53c6fc05024", "type": "subtopic", "title": "Classical Form and Rhetoric", "children": [{"id": "e511baaa-c68a-489d-8ff2-ad18372a18de", "type": "concept", "title": "Binary, rounded binary, sonata form, theme and variations, rondo"}, {"id": "fc684267-8f8b-4e8f-821e-d7b9dabfdd35", "type": "concept", "title": "Cadential rhetoric, modulation, and recapitulation"}, {"id": "09cfcd93-bf2c-4d90-a474-edc075c2663b", "type": "concept", "title": "Musical topics, wit, interruption, and social codes"}], "description": "The point is to connect form to expectation, memory, and dramatic argument."}, {"id": "c772a24f-dc63-473c-81f8-c4a308220ae2", "type": "subtopic", "title": "Institutions and Publics", "children": [{"id": "48cb87ca-0fae-4a3f-9440-5df0f8db97ff", "type": "concept", "title": "Court patronage and freelance careers"}, {"id": "c3377bae-0e25-4253-a935-3a8fa1849b0d", "type": "concept", "title": "Public concerts, publishing, and subscription culture"}, {"id": "2ac6bb42-796d-455d-9660-71f4deec8680", "type": "concept", "title": "Enlightenment sociability and amateur music-making"}], "description": "Students situate style inside changing systems of musical labor and listening."}]}, {"id": "32cf4be3-4f9b-4692-8d9b-ff5e6593102e", "type": "topic", "title": "Haydn and the Symphony", "description": "Haydn becomes a model for studying genre, craft, patronage, humor, motivic development, and the rise of instrumental music as public argument.", "children": [{"id": "cba37edb-ed09-48ed-8fc7-37d011bd2f4d", "type": "subtopic", "title": "Esterhazy, London, and Professional Identity", "children": [{"id": "633fc537-c530-41dc-a3d3-6244eb5c0fa8", "type": "concept", "title": "Kapellmeister labor and aristocratic patronage"}, {"id": "746d90b0-cfc8-42c4-89c8-b9532d86b0ce", "type": "concept", "title": "London symphonies and public concert life"}, {"id": "593a25a5-2ab5-4bc1-80c9-3c1d25e551a9", "type": "concept", "title": "Print circulation and international reputation"}], "description": "Students see Haydn's style as a response to real workplaces and publics."}, {"id": "239617ba-983f-4890-8f24-395ff8ccd478", "type": "subtopic", "title": "Symphonic Form and Development", "children": [{"id": "3d1fc2ae-f90d-4596-ba41-6dc85a6d25fb", "type": "concept", "title": "Exposition, development, recapitulation, coda"}, {"id": "88a39ae3-7fd2-4996-8e45-1c81da0529eb", "type": "concept", "title": "Monothematic strategies and motivic economy"}, {"id": "3bd074e4-e09b-4a23-ad54-dc4fe37faf9b", "type": "concept", "title": "Orchestral rhetoric, surprise, and pacing"}], "description": "The unit teaches students to track how small motives become large structures."}, {"id": "6aeb4093-8668-4a6a-8b8f-8f3db4ec3ad6", "type": "subtopic", "title": "String Quartet and Chamber Conversation", "children": [{"id": "7b7ba19a-75bc-49aa-87bb-ec7bcd65f2ef", "type": "concept", "title": "Op. 20, Op. 33, and late quartets"}, {"id": "c6504cbb-66a3-4c0c-872c-00a49889724c", "type": "concept", "title": "Four-part equality and conversational texture"}, {"id": "b75c32a7-6611-4fde-a1c9-84ddcfbfb905", "type": "concept", "title": "Genre hierarchy and domestic performance"}], "description": "Students examine chamber music as social dialogue and compositional laboratory."}]}, {"id": "2c3fe5b8-d913-4851-8ba1-ab7794a534ce", "type": "topic", "title": "Mozart's Operas and Instrumental Music", "description": "Mozart's work links operatic characterization, Classical form, concerto drama, social class, and theatrical timing.", "children": [{"id": "922e7ca2-4168-4553-9f88-a5a15b91e2a3", "type": "subtopic", "title": "Opera Buffa, Seria, and Singspiel", "children": [{"id": "0ba7ae27-072f-4552-be28-57c5bea657ca", "type": "concept", "title": "Le nozze di Figaro, Don Giovanni, Cosi fan tutte, Die Zauberflote"}, {"id": "553da810-bbd6-4cea-8220-64eff30db464", "type": "concept", "title": "Ensemble finales and dramatic simultaneity"}, {"id": "7e91ffee-5256-4a19-bad4-eb33e8cc7dd3", "type": "concept", "title": "Class, gender, servants, patrons, and comic timing"}], "description": "Students study opera as musical theater embedded in language, class, and stage convention."}, {"id": "b5d8bf2f-6976-4542-8e3e-f5428e187e77", "type": "subtopic", "title": "Concerto and Instrumental Drama", "children": [{"id": "010ead20-9fc0-41b9-8d9c-342a21108d6e", "type": "concept", "title": "Piano concerto as public self-fashioning"}, {"id": "48c58904-9b2a-4408-a9ef-ca3e2a40b1ec", "type": "concept", "title": "Ritornello-sonata hybrid procedures"}, {"id": "5b1fd0de-250a-44dc-a2d3-02a000145c95", "type": "concept", "title": "Soloist-orchestra dialogue"}], "description": "The unit shows how instrumental genres can behave theatrically."}, {"id": "3781f53d-815b-48ee-9b72-ac9b1a13d093", "type": "subtopic", "title": "Style, Form, and Affect", "children": [{"id": "60fdae62-4432-470f-97d4-cfef30f1f20f", "type": "concept", "title": "Chromaticism and tonal drama"}, {"id": "893ea534-5866-47e7-8527-b294559bbd24", "type": "concept", "title": "Phrase expansion and expressive timing"}, {"id": "19ded99f-836a-47f7-a6dd-0f97f789bc3c", "type": "concept", "title": "Chamber and symphonic craft"}], "description": "Students learn why Mozart's formal clarity can intensify ambiguity and emotion."}]}, {"id": "fe434cc8-2c21-4ccd-aaee-020ce9ebda60", "type": "topic", "title": "Beethoven", "description": "Beethoven anchors questions of revolution, individualism, sketch process, heroic rhetoric, late style, reception, and canon formation.", "children": [{"id": "71ba530a-de33-4d42-959e-7d4b6c8de941", "type": "subtopic", "title": "Heroic Style and Revolutionary Context", "children": [{"id": "eefc7cbe-52a1-42cd-b818-b77635bacf50", "type": "concept", "title": "Symphonies 3, 5, 6, and 9"}, {"id": "080932e3-79f6-4215-8d69-a1e7b96ea4d5", "type": "concept", "title": "Napoleonic Europe and civic ideals"}, {"id": "ce2506ed-666b-4c55-9b8b-73281c190ff1", "type": "concept", "title": "Motivic compression, expansion, and teleology"}], "description": "Students learn the historical meanings attached to scale, struggle, and public address."}, {"id": "12f926e5-de05-464c-b4e3-8e2d817b636b", "type": "subtopic", "title": "Sketches, Process, and Form", "children": [{"id": "56824245-0a33-4f05-bc34-e4893a38aa71", "type": "concept", "title": "Sketchbooks and source criticism"}, {"id": "1e5db01c-2770-4cd4-8fb1-3509e8c847b8", "type": "concept", "title": "Sonata cycle and variation procedures"}, {"id": "3e63819f-6092-4b83-9f6c-80d8fa470417", "type": "concept", "title": "Development, coda, and formal disruption"}], "description": "The point is to see composition as revision, labor, and argument."}, {"id": "5ad85947-a109-4978-9afb-ec71a3e335ba", "type": "subtopic", "title": "Late Style and Reception", "children": [{"id": "d7dd694a-d21c-4a74-85c3-ff333ad9bd7d", "type": "concept", "title": "Late quartets and piano sonatas"}, {"id": "0f8bf10f-7169-4ad4-b767-29d67f47dcf9", "type": "concept", "title": "Fugue, fragmentation, and inwardness"}, {"id": "013e23b0-f40d-4a4b-999f-46758fd1ea74", "type": "concept", "title": "Canonization, myth, deafness narratives, and performance traditions"}], "description": "Students ask how Beethoven became both historical person and cultural symbol."}]}, {"id": "55fbaca1-7659-4a14-aedc-5f77f80eaa9a", "type": "topic", "title": "Early Romanticism: Schubert and Schumann", "description": "This unit introduces Romantic interiority, literary imagination, fragment, memory, domestic performance, criticism, and new relationships between private and public art.", "children": [{"id": "ceabcbf1-09f5-4b9f-af94-bbf1a1179304", "type": "subtopic", "title": "Schubert and Lyric Expansion", "children": [{"id": "67dfbf2b-e518-4236-976a-3cf14d90e3d7", "type": "concept", "title": "Lied, piano sonata, chamber music, symphony"}, {"id": "4eee5638-ef54-4e98-9456-4b6ea05b0fa4", "type": "concept", "title": "Tonal wandering and enharmonic reinterpretation"}, {"id": "05e51ba1-cae4-42ff-87da-d502891e947c", "type": "concept", "title": "Domestic circles and posthumous reception"}], "description": "Students learn how songful melody and harmonic distance reshape Classical inheritance."}, {"id": "960b313e-2a7a-410c-a46c-fc8981a0e7be", "type": "subtopic", "title": "Schumann and Musical Criticism", "children": [{"id": "ca501811-1560-45e0-be73-22c694e80388", "type": "concept", "title": "Davidsbund, Florestan, Eusebius"}, {"id": "cacffc68-6ebe-4070-9adf-532b44a69fe6", "type": "concept", "title": "Character cycles and piano miniatures"}, {"id": "804f1517-6637-4e02-997a-091306bd6f87", "type": "concept", "title": "Neue Zeitschrift fur Musik and criticism"}], "description": "The unit connects composition to literature, journals, persona, and aesthetic debate."}, {"id": "2b97ee76-d8fb-443f-a687-e083f610b7da", "type": "subtopic", "title": "Romantic Subjectivity", "children": [{"id": "d67f1071-df62-4a3c-9ebe-7a973265f76e", "type": "concept", "title": "Fragment, fantasy, and cyclic return"}, {"id": "a356eb43-fa0c-4e0f-90ab-31fdb3c22525", "type": "concept", "title": "Nature, night, longing, and the uncanny"}, {"id": "a8035c7c-cdfc-4fe7-acb6-e7f10f352288", "type": "concept", "title": "Gendered domesticity and salon culture"}], "description": "Students examine the musical construction of selfhood and memory."}]}, {"id": "e73261d8-f2ee-4fb9-8d54-7ce2d2c24ff8", "type": "topic", "title": "The Art Song and Character Piece", "description": "Song and piano miniature make poetry, gesture, memory, and private performance central to nineteenth-century musical life.", "children": [{"id": "1296abd4-b7b6-4db3-b68d-9e160551f230", "type": "subtopic", "title": "Lied and Poetry", "children": [{"id": "ca238b18-4e47-42f0-a1e9-e5dc9c73c797", "type": "concept", "title": "Goethe, Heine, Muller, and poetic voice"}, {"id": "b71841a5-08d6-40cd-9bd7-c74bec23abed", "type": "concept", "title": "Strophic, modified strophic, and through-composed forms"}, {"id": "9cc35de1-b3a8-477c-9513-3bcbde30a2c7", "type": "concept", "title": "Piano postlude, motive, and narrative perspective"}], "description": "Students learn to read music and text as a single expressive structure."}, {"id": "fd3d53d2-157d-4484-a00f-b4d46679878e", "type": "subtopic", "title": "Piano Culture and Character Piece", "children": [{"id": "6a75aeb2-158f-4a8b-a506-2b32195fbdf5", "type": "concept", "title": "Nocturne, prelude, mazurka, impromptu, song without words"}, {"id": "c6607cf9-fd0c-4a4c-9264-2c591f04ef61", "type": "concept", "title": "Chopin, Mendelssohn, Fanny Hensel, Clara Schumann"}, {"id": "c3fd9d39-403c-43a9-8af6-57d14732c898", "type": "concept", "title": "Salon, pedagogy, publishing, and amateurs"}], "description": "The unit connects instrument technology, domestic markets, and concentrated form."}, {"id": "9fa7c060-2778-4ac8-b9aa-0c883323eb34", "type": "subtopic", "title": "Virtuosity and Persona", "children": [{"id": "7b6105c1-341b-4f54-a74c-e57dd370684f", "type": "concept", "title": "Liszt, Paganini, celebrity culture"}, {"id": "48adbdde-08a0-4dd5-aca2-b22a392565f2", "type": "concept", "title": "Transcription, paraphrase, and touring"}, {"id": "6340727f-adba-403d-98fd-89ee6be9db11", "type": "concept", "title": "Technique, embodiment, and public identity"}], "description": "Students distinguish spectacle from shallow display by studying social and musical function."}]}, {"id": "e6cbbbc6-8609-4d47-8bbd-a906d4c91802", "type": "topic", "title": "Romantic Opera: Verdi and Wagner", "description": "Romantic opera brings together voice, theater, politics, national language, myth, realism, industry, and the largest public arguments of the century.", "children": [{"id": "43b9d3c8-e4d7-4e09-b035-8011830ccaa9", "type": "subtopic", "title": "Italian Opera and Verdi", "children": [{"id": "5f79341e-6ea3-426b-9f48-e002ecb757e9", "type": "concept", "title": "Bel canto inheritance and scena structure"}, {"id": "66a6573d-14ee-48c8-a86a-7d563e664054", "type": "concept", "title": "Risorgimento, censorship, and public reception"}, {"id": "fc75962e-ced6-4f74-9c3a-e4817d950ba6", "type": "concept", "title": "Rigoletto, La traviata, Aida, Otello"}], "description": "Students study opera as theater, melody, politics, and popular culture."}, {"id": "b7b8f1e1-54a8-402a-9136-6c69fdbb975f", "type": "subtopic", "title": "Wagner and Music Drama", "children": [{"id": "7e5fdaca-dc27-4f5f-9c95-77c8baec7245", "type": "concept", "title": "Leitmotif, endless melody, and chromatic harmony"}, {"id": "d2fd08a4-9cad-4669-bc04-7a3027826982", "type": "concept", "title": "Gesamtkunstwerk and Bayreuth"}, {"id": "501b4a71-1a43-4be8-b4af-1dd7aacdcefb", "type": "concept", "title": "Myth, nationalism, antisemitism, and reception"}], "description": "The unit explores Wagner's artistic innovations alongside ideological and historical problems."}, {"id": "2c7523f2-44b8-4f45-b634-c894647c69d5", "type": "subtopic", "title": "Opera Institutions and Audiences", "children": [{"id": "694483b1-1dd2-41de-9e86-8e2fa3fc406f", "type": "concept", "title": "Opera houses, impresarios, singers, and star systems"}, {"id": "cbbfe24a-ef1c-466a-84cc-8edcea46d184", "type": "concept", "title": "Translation, touring, and repertory formation"}, {"id": "c7655c59-9746-4cb5-9f2e-f564988774a1", "type": "concept", "title": "Voice types, staging, and technology"}], "description": "Students examine who paid for opera, who performed it, and who claimed it."}]}, {"id": "2b06f3f7-6260-4604-a78d-ed7afea5474b", "type": "topic", "title": "The Symphonic Tradition: Brahms and Tchaikovsky", "description": "This unit studies the nineteenth-century symphony as inheritance, crisis, argument, nation, genre memory, and orchestral imagination.", "children": [{"id": "90d5e532-6f46-4f69-af91-99d7f35b5bae", "type": "subtopic", "title": "Absolute Music and Program Music", "children": [{"id": "52ebba90-59c0-4bfc-8227-4890af62f6f1", "type": "concept", "title": "Hanslick, Liszt, Wagner, and critical positions"}, {"id": "107836b9-1b6b-4f17-8d34-5c00ef41b0ce", "type": "concept", "title": "Berlioz and programmatic imagination"}, {"id": "3ea04181-6ce7-4969-93c4-8192c1145475", "type": "concept", "title": "Tone poem and symphonic poem"}], "description": "Students learn a central nineteenth-century debate about meaning in instrumental music."}, {"id": "3af3149d-ea65-436f-876f-0391d9df1a98", "type": "subtopic", "title": "Brahms and Historical Consciousness", "children": [{"id": "9cffb236-7e95-429f-ad66-8b464312a6a7", "type": "concept", "title": "Motivic development and variation"}, {"id": "66185383-9cb9-40e5-aa0f-3113b2a1a922", "type": "concept", "title": "Classical forms under Romantic weight"}, {"id": "370152f3-1f8f-4220-a06a-1f5c571ef617", "type": "concept", "title": "Brahms reception, anxiety of influence, and canon"}], "description": "The unit shows how tradition can become creative pressure."}, {"id": "f4fd5ad9-7007-4e2c-b7e2-57218a0346f9", "type": "subtopic", "title": "Tchaikovsky, Mendelssohn, and Orchestral Voice", "children": [{"id": "f83254ea-b7fb-491e-9bbe-c59c9e840796", "type": "concept", "title": "Cyclic form, lyricism, and fate narratives"}, {"id": "ca5b23bc-9b71-4c60-9843-6bd088e0bf46", "type": "concept", "title": "Orchestral color and ballet/drama connections"}, {"id": "ba5d5332-9687-4b3a-b32f-5d9ff49fba1b", "type": "concept", "title": "Cosmopolitanism and national expectation"}], "description": "Students compare symphonic identity across institutions and traditions."}]}, {"id": "698f4e2d-969a-4e60-8eb2-30d9f5cd80ad", "type": "topic", "title": "Nationalism in Music", "description": "Nationalism is treated as a historical process shaped by language, folklore, empire, education, print, politics, and reception, not as a simple list of national styles.", "children": [{"id": "999adcf4-f162-4935-bedd-1ca0b111d259", "type": "subtopic", "title": "Folk Materials and Invention", "children": [{"id": "4e3a6b91-3f58-4288-9b35-c3702bae6704", "type": "concept", "title": "Dance rhythms, modes, drones, and folk quotation"}, {"id": "1d14706d-ad1d-4c7b-8830-a631b6f3d478", "type": "concept", "title": "Urban nationalism and rural imagination"}, {"id": "d290c9a1-aa5c-4f6b-8dbe-d52d0ef8583a", "type": "concept", "title": "Authenticity debates"}], "description": "Students ask how composers collected, arranged, imagined, or manufactured national sound."}, {"id": "20a74897-5a2f-420b-9d15-8b21471535ca", "type": "subtopic", "title": "Nation, Empire, and Identity", "children": [{"id": "babac7ac-9e56-45f9-833c-7d041f9b2c3c", "type": "concept", "title": "Smetana, Dvorak, Grieg, Mussorgsky, Glinka, nationalist schools"}, {"id": "7ed094b4-9680-428e-a091-8e17f5f5ad90", "type": "concept", "title": "Colonial and imperial exhibition culture"}, {"id": "1416600a-435b-4f4f-b74b-1e92b5d172fb", "type": "concept", "title": "Race, ethnicity, class, and exoticism"}], "description": "The unit makes power visible in musical culture."}, {"id": "5835782a-a30c-47dc-9e43-872dfce643c0", "type": "subtopic", "title": "Institutions of National Music", "children": [{"id": "72ffbeec-4330-49ed-9956-355d53e108d7", "type": "concept", "title": "Conservatories, festivals, opera houses, criticism"}, {"id": "c1fda6dd-dc24-4120-82cb-cf15d9b9184c", "type": "concept", "title": "Publishing, education, and canon building"}, {"id": "81531e1d-f37a-4b04-b57a-6369e83588de", "type": "concept", "title": "Transnational circulation and migration"}], "description": "Students see nationalism as infrastructure."}]}, {"id": "2e1e7a23-22f8-449c-a5ab-8aae026dcc9b", "type": "topic", "title": "Late Romanticism", "description": "Late Romanticism pushes tonality, orchestration, scale, psychology, and historical consciousness toward the thresholds of modernism.", "children": [{"id": "b19d732d-13ce-4993-8958-a3a2677e67ad", "type": "subtopic", "title": "Expanded Tonality and Chromaticism", "children": [{"id": "f8def9d6-db04-492b-add7-d012664d7492", "type": "concept", "title": "Wagnerian chromatic legacy"}, {"id": "1e12b024-3cdd-498f-bf41-9b73e71691ee", "type": "concept", "title": "Mahler, Strauss, Wolf, Bruckner"}, {"id": "c17d1a21-bf02-4762-bc51-e1943178a8db", "type": "concept", "title": "Dissonance, modulation, and tonal ambiguity"}], "description": "Students hear how late-Romantic harmony stretches expectation without abandoning inherited forms."}, {"id": "716f91c3-d9d1-46d9-81fe-42a5045a4fd0", "type": "subtopic", "title": "Orchestral Modernity", "children": [{"id": "a4b002b6-f2f0-46e7-a5f8-3494269b3386", "type": "concept", "title": "Expanded orchestra and timbral imagination"}, {"id": "d63c7e2e-ca7f-4f4e-a7ab-20336f6f2485", "type": "concept", "title": "Tone poem, symphony, and song cycle"}, {"id": "9ee501ac-839d-4b12-abc4-a2e57cc96f99", "type": "concept", "title": "Technology, concert halls, and listening publics"}], "description": "The unit focuses on scale, color, and public meaning."}, {"id": "b5abb383-f651-40a5-8856-92f09cf133d9", "type": "subtopic", "title": "Historiography and the Edge of Modernism", "children": [{"id": "342a8b4b-9ba6-42da-a3f7-12732ef0f308", "type": "concept", "title": "Fin-de-siecle culture"}, {"id": "b4f714e1-bfd7-42da-9439-06e5421be632", "type": "concept", "title": "Decadence, psychology, and crisis narratives"}, {"id": "f3e63ad7-360b-4aa7-bc27-f1378c6e78df", "type": "concept", "title": "Periodization, canon gaps, and reception history"}], "description": "Students learn to narrate transition carefully instead of treating modernism as inevitable."}]}, {"id": "1cf42715-f164-4de7-93c8-0c273ebab641", "type": "topic", "title": "Performance Practice, Sources, and Historiography", "description": "A world-class survey teaches students not only what happened, but how we know. This added unit makes evidence, performance, editions, recordings, and scholarly debate explicit across the course.", "children": [{"id": "9ff4ac25-a76f-48e0-a4a2-0854144997a8", "type": "subtopic", "title": "Historical Performance and Instruments", "children": [{"id": "80f088e2-c08c-4d23-aeb5-ae64acd0f094", "type": "concept", "title": "Fortepiano, piano technology, strings, winds, brass, and timpani"}, {"id": "699dfdea-7b7c-44e5-96dc-249b5dc91b87", "type": "concept", "title": "Tempo, articulation, vibrato, rubato, and ornament"}, {"id": "ef4e2807-